     */
    case targetIdentifyFailed
    /**
     * 固件文件扩展名或格式不受支持。
     */
    case unsupportedFirmwareFormat
    /**
     * BIN 固件缺少基地址。
     */
    case missingBinBaseAddress
    /**
     * 固件地址格式、对齐或范围无效。
     */
    case invalidFirmwareAddress
    /**
     * probe-rs 底层操作失败。
     */
    case probeRsFailure
    /**
     * 文件系统读写失败。
     */
    case ioFailure
    /**
     * 用户输入未通过校验。
     */
    case invalidUserInput
    /**
     * 本地配置、历史或日志存储失败。
     */
    case storageFailure
    /**
